args.ReplacementContent:
{/* Tour Date Show Card Info */}
{(() => {
  const activeShow = activeDropDay ? getDayShow(activeDropDay) : null;
  if (!activeShow) return null;
  return (
    <div className="shrink-0 bg-amber-500/5 border border-amber-500/20 rounded-lg px-2.5 h-[30px] flex items-center justify-between gap-2">
      <div className="flex items-center gap-1.5 min-w-0">
        <span className="text-[11px] shrink-0">🎸</span>
        <span className="text-[10px] font-black text-white truncate">{activeShow.venue}</span>
        <span className="text-[9px] text-white/40 truncate shrink-0">({activeShow.city}{activeShow.state ? `, ${activeShow.state}` : ''})</span>
        {activeShow.notes && (
          <span className="text-[9px] text-amber-300/50 italic truncate ml-1.5" title={activeShow.notes}>
            Note: {activeShow.notes}
          </span>
        )}
      </div>
    </div>
  );
})()}

{/* Crew Response Status Details */}
{editingShiftId && (() => {
  const shift = schedules.find(s => s.id === editingShiftId);
  if (!shift || !shift.approvalStatus || shift.crewId === 'openshifts') return null;
  return (
    <div className={`p-3 border rounded-xl flex flex-col gap-1.5 ${
      shift.approvalStatus === 'approved'
        ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
        : shift.approvalStatus === 'declined'
        ? 'bg-rose-500/10 border-rose-500/20 text-rose-400'
        : 'bg-amber-500/10 border-amber-500/20 text-amber-300'
    }`}>
      <div className="flex items-center justify-between">
        <span className="text-[9px] font-black uppercase tracking-wider">Crew Response Status</span>
        <span className="text-[10px] font-black uppercase">
          {shift.approvalStatus === 'approved' ? '✓ Approved' : shift.approvalStatus === 'declined' ? '✗ Declined' : '⏳ Pending'}
        </span>
      </div>
      {shift.approvalStatus === 'declined' && shift.declineReason && (
        <div className="border-t border-rose-500/20 pt-1.5 mt-0.5">
          <p className="text-[8px] text-rose-400/60 font-bold uppercase tracking-wider">Reason for Declining:</p>
          <p className="text-xs text-rose-200/90 leading-relaxed italic mt-0.5 font-bold">
            “{shift.declineReason}”
          </p>
        </div>
      )}
    </div>
  );
})()}

